class AlertConsumer(AsyncJsonWebsocketConsumer):
    async def receive_json(self, content):
        if content.get('command') == 'dismiss_alert':
            alert_id = content.get('alert_id')
            updated = await database_sync_to_async(
                SecurityAlert.objects.filter(id=alert_id, user=self.scope['user']).update
            )(is_dismissed=True)
            if not updated:
                await self.send_json({'error': 'Alert not found or unauthorized'})
                return
            await self.send_json({'status': 'dismissed', 'alert_id': alert_id})
